import React, { useEffect, useState } from "react";

const API_URL = "http://localhost:5000";

function CandidatesPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await fetch(`${API_URL}/api/candidates`);
        const data = await res.json();
        setCandidates(data);
      } catch (err) {
        console.error("Failed to fetch candidates:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchCandidates();
  }, []);

  return (
    <div style={{ minHeight: "100vh", backgroundColor: "#f5f5f5" }}>
      
      {/* 🔴 CURVED HEADER */}
      <div
        style={{
          background: "linear-gradient(to right, #C8102E, #8B0000)",
          padding: "35px 0",
          textAlign: "center",
          color: "white",
          fontSize: "30px",
          fontWeight: "bold",
          letterSpacing: "1px",
          borderBottomLeftRadius: "50px",
          borderBottomRightRadius: "50px",
          boxShadow: "0 8px 20px rgba(0,0,0,0.2)",
        }}
      >
        Candidates
      </div>

      {/* CONTENT */}
      <div style={{ padding: 30 }}>
        {loading && (
          <p style={{ textAlign: "center" }}>Loading candidates...</p>
        )}

        {!loading && candidates.length === 0 && (
          <p style={{ textAlign: "center" }}>No candidates available.</p>
        )}

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))",
            gap: 25,
            marginTop: 20,
          }}
        >
          {candidates.map((c) => (
            <div
              key={c._id}
              style={{
                backgroundColor: "#ffffff",
                borderRadius: 15,
                padding: 20,
                boxShadow: "0 6px 18px rgba(0,0,0,0.08)",
                textAlign: "center",
                borderTop: "5px solid #C8102E",
                transition: "0.3s ease",
              }}
              onMouseEnter={(e) =>
                (e.currentTarget.style.transform = "translateY(-6px)")
              }
              onMouseLeave={(e) =>
                (e.currentTarget.style.transform = "translateY(0)")
              }
            >
              {c.image ? (
                <img
                  src={`${API_URL}/uploads/${c.image}`}
                  alt={`${c.firstName} ${c.lastName}`}
                  style={{
                    width: "100%",
                    height: 180,
                    objectFit: "cover",
                    borderRadius: 12,
                    marginBottom: 15,
                  }}
                />
              ) : (
                <div
                  style={{
                    width: "100%",
                    height: 180,
                    backgroundColor: "#ddd",
                    borderRadius: 12,
                    marginBottom: 15,
                  }}
                />
              )}

              <h3 style={{ color: "#8B0000", marginBottom: 8 }}>
                {c.firstName} {c.lastName}
              </h3>

              <p><strong>Candidacy:</strong> {c.candidacy}</p>
              <p><strong>Partylist:</strong> {c.partylist}</p>
              <p style={{ fontSize: 14, color: "#555" }}>
                {c.description || "No description provided"}
              </p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default CandidatesPage;
